// Generated by the Salvo compiler: the actor scheduler — asynchronous
// effect handlers' runtime. The Kotlin mirror of the Rust backend's
// scheduler module; the semantics are LANGUAGE_SPEC.md's [actor-kind] …
// [actor-watch] and must stay identical on both
// backends: run-to-completion activations on pool threads, per-actor
// bounded queues (bound explicit at spawn; a full queue blocks the
// sender), reply tokens with reserved capacity (a reply never blocks and
// never counts against the bound), the gate (at most one outstanding per
// actor; while gated only the awaited reply is delivered), death = a
// faulted activation caught at the dispatch boundary (sends and replies
// to the dead are silent no-ops; watchers are notified with the reason),
// the quiescence hook ([actor-on-idle]: a registered token answered when
// nothing anywhere can run), and the deadlock report — nothing left that can
// run while a frame waits, and no hook to fire, is a named runtime error
// rather than a hang. The waiting frame need not be main: an activation
// parked in a nested wait holds its actor's `running` flag, so its own
// mailbox is stalled while it waits, and the report counts parked frames out
// of the running ones. Pool threads are daemon threads: the program ends when
// main returns.
//
// [main-pool] [waitfor-pump] `main` is the **single worker of its own pool**
// (pool 0), which is given no thread of its own: main's thread is the
// worker, and it works while it waits. A wait therefore *serves* its pool
// rather than merely blocking on it — the uniform rule is that a `waitfor`
// serves its own pool's work except activations of the actor doing the
// waiting, so a waiting actor's mailbox stays stalled (serialization is
// preserved) while main, which has no mailbox, serves everything placed on
// its pool. Blocking is the degenerate case of an empty queue.
package salvo

import kotlin.concurrent.withLock

/** An actor body: state plus one entry point per kind of delivery. */
interface SalvoActor {
    /** A user message (a `send fn` invocation). */
    fun handle(ctx: SalvoCtx, msg: Any?)

    /** A reply delivery: the slot names the parked continuation. */
    fun resume(ctx: SalvoCtx, slot: Long, value: Any?)
}

/** Passed to every activation: the actor's own identity. */
class SalvoCtx(val addr: Int)

private sealed class SalvoEntry {
    class User(val msg: Any?) : SalvoEntry()

    class Reply(val slot: Long, val value: Any?) : SalvoEntry()
}

private class SalvoActorState(val bound: Int, val pool: Int, var body: SalvoActor?) {
    val queue = ArrayDeque<SalvoEntry>()
    var userLen = 0
    var gate: Long? = null
    var running = false
    var dead = false

    /**
     * The host's account of the fault that killed it, kept so a watch
     * registered *after* the death answers what the earlier watchers got.
     */
    var exitReason: String? = null

    /**
     * [actor-watch] Registered death watches: the token to fulfil and the
     * **builder** generated code handed over with it, which turns the reason
     * into the language's `Exit` value. The runtime cannot construct a Salvo
     * class, so the watch site supplies the constructor.
     */
    val watchers = mutableListOf<Pair<SalvoReply, (String) -> Any?>>()

    /**
     * [actor-on-idle] Reply tokens aimed at this actor that nobody has
     * discharged — the continuations it is still owed. A token whose holder
     * died stays counted, which is the honest answer: the obligation is
     * genuinely lost.
     */
    var owed = 0
}

private class SalvoWaiterState(val pool: Int) {
    var value: Any? = null
    var filled = false

    /**
     * [waitfor-pump] While this waiter is parked: whether a frame is sitting
     * on it, and the actor whose activation that frame is, if it is one
     * ([parkedActor] is null for main and for a task). What the deadlock
     * report reads to name the **occupied** actors — the ones whose mailbox
     * is stalled by a wait nested inside an activation.
     */
    var parked = false
    var parkedActor: Int? = null
}

/**
 * [main-pool] [waitfor-pump] Where a thread is: the pool it works for, the
 * actor whose activation it is currently inside (`null` on main, inside a task
 * and between activations), and whether it is inside a frame the scheduler
 * counts in `active` at all. The pool is what an `on`-less spawn or mint
 * inherits; the actor is the one thing a wait must not serve; [frame]
 * distinguishes main's own thread from a task running on the main pool, which
 * is what a wait has to know to book itself correctly.
 */
private class SalvoHere(val pool: Int, val actor: Int?, val frame: Boolean = false)

/**
 * [task-mint] What a pool owns besides its worker threads: a queue of
 * detached tasks, and the sink an uncaught fault on it is reported to
 * [pool-fault-sink] (`null` is the named runtime report).
 */
private class SalvoPoolState {
    /** Tasks whose answer has arrived, in the order it arrived. */
    val tasks = ArrayDeque<Pair<(Any?) -> Unit, Any?>>()
    var sinkAddr: Int? = null
    var sinkBuild: ((String) -> Any?)? = null

    /**
     * [actor-on-idle] Undischarged tokens that belong to this pool without
     * belonging to an actor on it: a task waiting for its answer, and the
     * token a frame working for this pool is parked on.
     */
    var owed = 0
}

/**
 * The scheduler: one shared lock (its own monitor) over all state, pool
 * worker threads, and the waiter bridge for `main`.
 */
object SalvoSched {
    /**
     * [main-pool] The pool main is the single worker of. It never gets a
     * worker thread: main's own thread runs its work, while it waits.
     */
    const val MAIN_POOL = 0

    private val lock = java.util.concurrent.locks.ReentrantLock()
    private val cv = lock.newCondition()
    private val actors = mutableListOf<SalvoActorState>()
    private val waiters = mutableListOf<SalvoWaiterState>()
    // [main-pool] Pool 0 exists from the start and belongs to main.
    private val pools = mutableListOf(SalvoPoolState())
    private var nextSlot = 0L
    private var active = 0

    /**
     * [waitfor-pump] Of the [active] frames, the ones parked in a wait: an
     * activation or a task whose frame is alive on some thread's stack but
     * which cannot proceed until its token arrives. It still holds its actor's
     * `running` flag — so its mailbox is stalled and nobody else will serve it
     * — which is why a parked frame is *not* progress and must not hide a
     * deadlock. `active - parkedFrames` is the number of frames that can still
     * get somewhere on their own.
     */
    private var parkedFrames = 0

    /**
     * [waitfor-pump] How deep main's own thread is in a wait. main is the one
     * thread that runs program code without being a frame the scheduler
     * counts, so while it is *not* waiting it is progress the scheduler cannot
     * see, and no deadlock may be declared.
     */
    private var mainWaits = 0

    /**
     * [actor-on-idle] Registered quiescence hooks: the pool whose obligations
     * the answer reports, the token to fulfil, and the builder for its
     * payload. Taken as a whole when the scheduler settles — every
     * registration is a one-shot.
     */
    private val idleHooks = mutableListOf<Triple<Int, SalvoReply, (Int, Int) -> Any?>>()

    /**
     * [time-timer] Registered deadlines, each a monotonic reading with the
     * token to fulfil when it passes and the builder for the `Fired` payload.
     * Unordered, exactly as on the Rust side: a program registers few
     * deadlines at a time, so one scan per wake beats keeping a heap ordered
     * under the scheduler's own lock.
     */
    private val timers = mutableListOf<Triple<Long, SalvoReply, (Long) -> Any?>>()

    /**
     * [time-timer] Whether the deadline thread is running. Started by the
     * first [after], so a program that never sets a timer has no timer thread
     * — and one that does has exactly one, never a thread per timer.
     */
    private var timerThread = false
    private val here = ThreadLocal.withInitial { SalvoHere(MAIN_POOL, null) }

    /** Creates a pool of [n] daemon worker threads and answers its id. */
    fun pool(n: Int): Int = poolWithSink(n, null, null)

    /**
     * [pool-fault-sink] The same, with an actor to report uncaught faults to:
     * the addr and the builder that turns the host's reason into the
     * language's `Fault` value (the runtime cannot construct one, exactly as
     * with `Exit` [actor-watch]).
     */
    fun poolWithSink(
        n: Int,
        sinkAddr: Int?,
        sinkBuild: ((String) -> Any?)?,
    ): Int {
        val id =
            lock.withLock {
                val state = SalvoPoolState()
                state.sinkAddr = sinkAddr
                state.sinkBuild = sinkBuild
                pools.add(state)
                pools.size - 1
            }
        repeat(n) {
            Thread { worker(id) }.apply {
                isDaemon = true
                start()
            }
        }
        return id
    }

    /**
     * [task-mint] Mints a token whose fulfilment **schedules** [body] on
     * [pool]. No capacity is reserved and no queue can be full: a task has no
     * mailbox, which is why a task mint contributes no deadlock edge.
     */
    fun mintTask(
        pool: Int,
        body: (Any?) -> Unit,
    ): SalvoReply =
        lock.withLock {
            nextSlot += 1
            pools[pool].owed += 1
            SalvoReply(SalvoTargetTask(pool, body), nextSlot)
        }

    /**
     * [main-pool] The pool the calling thread works for — what a spawn or a
     * mint with no `on` clause inherits. Main's thread answers [MAIN_POOL].
     */
    fun currentPool(): Int = here.get().pool

    /**
     * [waitfor-dedicated] A pool of exactly one thread, for work that may
     * occupy its thread until an answer arrives. Identical to `pool(1)` at
     * run time — what makes it different is static: the language types it as
     * a `Dedicated Pool` and the `on` clause consumes it, so a dedicated
     * thread has exactly one occupant.
     */
    fun thread(): Int = pool(1)

    /** Spawns an actor on a pool. The queue bound is explicit and required. */
    fun spawn(pool: Int, bound: Int, body: SalvoActor): Int =
        lock.withLock {
            actors.add(SalvoActorState(bound, pool, body))
            actors.size - 1
        }

    /**
     * Sends a user message. Blocks while the target's queue is full; a
     * send to a dead actor is a silent no-op.
     *
     * [main-pool] One block is a *guaranteed* wedge rather than
     * back-pressure: the main pool has exactly one worker — main's own
     * thread, which serves work only inside a `waitfor` — so a full
     * main-pool mailbox blocked on from that same thread can never drain.
     * Reported by name instead of hung.
     */
    fun send(addr: Int, msg: Any?) {
        lock.withLock {
            while (!actors[addr].dead && actors[addr].userLen >= actors[addr].bound) {
                if (currentPool() == MAIN_POOL && actors[addr].pool == MAIN_POOL) {
                    reportMainPoolWedge(addr)
                }
                cv.await()
            }
            if (actors[addr].dead) {
                return
            }
            actors[addr].queue.addLast(SalvoEntry.User(msg))
            actors[addr].userLen += 1
            cv.signalAll()
        }
    }

    /**
     * [main-pool] The full-main-pool-mailbox report: a named error, since
     * the only thread that could drain the queue is the one blocked on it.
     */
    private fun reportMainPoolWedge(addr: Int): Nothing {
        System.err.println(
            "salvo: deadlock: the main pool's actor $addr has a full mailbox and the " +
                "only thread that could drain it is the one sending: the main pool has one " +
                "worker, `main` itself, and it serves work only inside a `waitfor` — send " +
                "fewer messages before waiting, raise the handler's `mailbox` capacity, or " +
                "place the actor on a pool of its own",
        )
        kotlin.system.exitProcess(1)
    }

    /**
     * Mints a reply token targeting a actor's parked continuation, and
     * answers the slot beside it: the slot is what generated code keys its
     * parked-continuation table by. A `Pair`, like [waiter], and the mirror
     * of the Rust runtime's `salvo_mint`.
     */
    fun mint(addr: Int): Pair<SalvoReply, Long> =
        lock.withLock {
            nextSlot += 1
            actors[addr].owed += 1
            Pair(SalvoReply(SalvoTargetProc(addr), nextSlot), nextSlot)
        }

    /**
     * Mints a *gated* reply token: until it is delivered, the actor
     * serves nothing else. At most one gate may be outstanding — a second
     * is a fault in the calling activation.
     */
    fun mintGated(addr: Int): Pair<SalvoReply, Long> =
        lock.withLock {
            check(actors[addr].gate == null) { "a gated continuation is already outstanding" }
            nextSlot += 1
            actors[addr].gate = nextSlot
            actors[addr].owed += 1
            Pair(SalvoReply(SalvoTargetProc(addr), nextSlot), nextSlot)
        }

    /**
     * [actor-watch] Registers a death watch: [onExit] is sent the `Exit`
     * [exit] builds when the actor dies. Watching an already-dead actor
     * answers immediately, with the reason its death recorded — so a watch
     * that loses the race to a fast fault is not a watch that never answers.
     */
    fun watch(
        addr: Int,
        onExit: SalvoReply,
        exit: (String) -> Any?,
    ) {
        lock.withLock {
            untrack(onExit)
            if (actors[addr].dead) {
                deliverReply(onExit, exit(actors[addr].exitReason ?: "fault"))
                cv.signalAll()
            } else {
                actors[addr].watchers.add(Pair(onExit, exit))
            }
        }
    }

    /**
     * [actor-on-idle] Registers a quiescence hook: [notify] is sent the `Idle`
     * [idle] builds the moment nothing anywhere can run, reporting what [pool]
     * is still owed. One-shot, exactly as a watch is — delivering the answer is
     * work, which ends the idleness that produced it.
     *
     * The registration itself wakes every worker: the scheduler may *already*
     * be settled, in which case the next thread to look fires the hook.
     */
    fun onIdle(
        pool: Int,
        notify: SalvoReply,
        idle: (Int, Int) -> Any?,
    ) {
        lock.withLock {
            untrack(notify)
            idleHooks.add(Triple(pool, notify, idle))
            cv.signalAll()
        }
    }

    /**
     * [time-timer] Registers a deadline: [done] is sent the `Fired` [fired]
     * builds once at least [delay] nanoseconds have passed, carrying the
     * monotonic reading it fired at.
     *
     * One thread serves every deadline, started on the first registration and
     * parked in a timed wait until the earliest one comes due — the same shape
     * as the Rust backend's, and for the same reason: no thread per timer, no
     * polling. A registration wakes it, since the new deadline may be earlier
     * than the one it is sleeping on.
     *
     * A delay of zero or less fires at the next look rather than immediately:
     * the answer is always a *later* activation, never a call inside `after`.
     */
    fun after(
        delay: Long,
        done: SalvoReply,
        fired: (Long) -> Any?,
    ) {
        lock.withLock {
            // The token is the scheduler's obligation now, exactly as with a
            // watch or an idle hook [actor-on-idle].
            untrack(done)
            val deadline = SalvoTime.monoNanos() + if (delay < 0L) 0L else delay
            timers.add(Triple(deadline, done, fired))
            if (!timerThread) {
                timerThread = true
                val t = Thread { serveTimers() }
                t.isDaemon = true
                t.start()
            }
            cv.signalAll()
        }
    }

    /**
     * [time-timer] The deadline thread: delivers every timer whose deadline
     * has passed, then sleeps until the earliest one left (or until something
     * changes). It never exits — the program ends when main returns
     * [actor-waitfor], and pending timers die with it (the thread is a daemon,
     * so it does not hold the JVM open).
     */
    private fun serveTimers() {
        lock.lock()
        try {
            while (true) {
                val now = SalvoTime.monoNanos()
                val due = timers.filter { it.first <= now }
                if (due.isNotEmpty()) {
                    timers.removeAll(due)
                    for ((deadline, done, fired) in due) {
                        deliverReply(done, fired(deadline))
                    }
                    cv.signalAll()
                    continue
                }
                val earliest = timers.minOfOrNull { it.first }
                if (earliest == null) {
                    cv.await()
                } else {
                    cv.awaitNanos(earliest - now)
                }
            }
        } finally {
            lock.unlock()
        }
    }

    /** A waiter: the `waitfor` bridge. Answers (token, waiter id). */
    fun waiter(): Pair<SalvoReply, Int> =
        lock.withLock {
            val pool = currentPool()
            waiters.add(SalvoWaiterState(pool))
            nextSlot += 1
            pools[pool].owed += 1
            Pair(SalvoReply(SalvoTargetWaiter(waiters.size - 1), nextSlot), waiters.size - 1)
        }

    /**
     * [waitfor-pump] Blocks the calling thread until the waiter's token is
     * sent, and answers the value — *serving this thread's pool while it
     * waits* (everything on it except the waiting actor's own activations,
     * which stay stalled). For main, whose pool has no other worker, that is
     * what runs main-pool work at all; where the queue is empty the wait is a
     * plain block. If nothing can run while this frame waits, reports the
     * deadlock instead of hanging — including when the waiting frame is an
     * **occupied actor**, whose own mailbox its wait has stalled.
     */
    fun awaitReply(wid: Int): Any? {
        val spot = here.get()
        lock.lock()
        try {
            // This frame is parked for the whole call, including across the
            // jobs the pump runs below: each of those books itself in `active`
            // on its own, so `active - parkedFrames` stays the count of frames
            // that can still proceed.
            enterWait(spot, wid)
            while (true) {
                if (waiters[wid].filled) {
                    waiters[wid].filled = false
                    leaveWait(spot, wid)
                    return waiters[wid].value
                }
                // [waitfor-pump] Detached tasks are what the rule names
                // first, and they are served whoever is waiting; activations
                // are served except the waiter's own.
                if (pools[spot.pool].tasks.isNotEmpty()) {
                    runTask(spot.pool)
                    continue
                }
                val job = pick(spot.pool, spot.actor)
                if (job != null) {
                    runJob(job.first, job.second)
                    continue
                }
                // [actor-on-idle] Nothing to run is exactly the event the hooks
                // are registered for, and firing one *is* progress — so it comes
                // before the deadlock report, which is what firing nothing
                // leaves.
                if (fireIdle()) {
                    continue
                }
                if (stuck()) {
                    reportDeadlock(spot.actor)
                }
                cv.await()
            }
        } finally {
            lock.unlock()
        }
    }

    /**
     * [waitfor-pump] Books the calling frame as parked on [wid]: an activation
     * or a task counts out of the frames that can still proceed, and main's own
     * thread — which the scheduler never counts as a frame — records that it is
     * inside a wait at all, since main running program code is progress nothing
     * else can see.
     */
    private fun enterWait(
        spot: SalvoHere,
        wid: Int,
    ) {
        waiters[wid].parked = true
        waiters[wid].parkedActor = spot.actor
        if (spot.frame) {
            parkedFrames += 1
        } else if (spot.pool == MAIN_POOL) {
            mainWaits += 1
        }
    }

    /**
     * The exact reverse, on every way out of a wait. Clamped at zero, so an
     * unbalanced pair cannot turn the counts into a permanent "everything is
     * stuck".
     */
    private fun leaveWait(
        spot: SalvoHere,
        wid: Int,
    ) {
        waiters[wid].parked = false
        waiters[wid].parkedActor = null
        if (spot.frame) {
            parkedFrames = clamp(parkedFrames - 1)
        } else if (spot.pool == MAIN_POOL) {
            mainWaits = clamp(mainWaits - 1)
        }
    }

    internal fun sendReply(reply: SalvoReply, value: Any?) {
        lock.withLock {
            deliverReply(reply, value)
            cv.signalAll()
        }
    }

    /** Delivery under the lock: reserved capacity, no-op to the dead. */
    private fun deliverReply(reply: SalvoReply, value: Any?) {
        // [actor-on-idle] The obligation is met here, whatever the target does
        // with the value — including a no-op delivery to the dead.
        untrack(reply)
        when (val target = reply.target) {
            is SalvoTargetWaiter -> {
                waiters[target.wid].value = value
                waiters[target.wid].filled = true
            }
            is SalvoTargetProc -> {
                if (actors[target.addr].dead) {
                    return
                }
                actors[target.addr].queue.addLast(SalvoEntry.Reply(reply.slot, value))
            }
            // [task-mint] The answer schedules the task. Nothing to check: a
            // task has no mailbox to fill and no death to be a no-op for.
            is SalvoTargetTask -> {
                pools[target.pool].tasks.addLast(Pair(target.body, value))
            }
        }
    }

    /** The first deliverable entry for an actor, honouring the gate. */
    private fun deliverable(p: SalvoActorState): Int? {
        if (p.running || p.dead) {
            return null
        }
        val gate = p.gate ?: return if (p.queue.isEmpty()) null else 0
        val at = p.queue.indexOfFirst { it is SalvoEntry.Reply && it.slot == gate }
        return if (at < 0) null else at
    }

    /**
     * True when no work is *queued* anywhere: no actor has a deliverable
     * entry, no pool has a scheduled task, no deadline is pending, and no
     * parked frame has an answer sitting in its slot.
     *
     * [waitfor-pump] That last clause is a queue too, even though it looks
     * like a variable: a fulfilled waiter slot is work whose *pickup is the
     * waiting thread itself*, which will take it at the top of its next pass.
     * Between the delivery and the pickup the frame is still booked as parked,
     * so without this clause a thread that looked in that window would call a
     * program stuck one instant before it proceeds.
     *
     * [time-timer] A pending deadline counts as work on its way: the timer
     * thread will deliver it, so a program waiting for a fire is neither
     * quiescent ([actor-on-idle]) nor deadlocked — it is waiting for time to
     * pass, which is the one thing that happens without anybody running.
     */
    private fun quiet(): Boolean =
        actors.all { deliverable(it) == null } &&
            pools.all { it.tasks.isEmpty() } &&
            timers.isEmpty() &&
            waiters.none { it.parked && it.filled }

    /**
     * True when nothing can ever run again without outside input: no
     * activation is running and nothing is queued.
     *
     * [actor-on-idle] What the quiescence hook fires on. A frame parked in a
     * `waitfor` counts as running here, so idleness does not fire while any
     * wait is in flight — the stated caveat of the rule.
     */
    private fun idle(): Boolean = active == 0 && quiet()

    /**
     * True when nothing can ever run again *and* somebody is waiting for
     * something — the deadlock condition, which is weaker than [idle] in
     * exactly one way: a frame **parked in a wait** is not progress.
     *
     * [waitfor-pump] Every clause is a thread that could still get somewhere:
     * `active - parkedFrames > 0` is a frame running rather than parked (a body
     * between two waits, or a sender blocked on a full mailbox, which will
     * proceed when the mailbox drains); `mainWaits == 0` is main's thread
     * running program code, which the scheduler does not count as a frame and
     * therefore cannot see; `!quiet()` is something queued for whoever runs
     * next. With all of them false, every thread the scheduler knows about is
     * parked on an answer and nothing is queued to produce one. The remaining
     * blind spot is stated with [actor-on-idle] and is the same one the report
     * has always had — a platform handler with a thread of its own can inject
     * work the scheduler never saw.
     */
    private fun stuck(): Boolean = active == parkedFrames && mainWaits > 0 && quiet()

    /**
     * [actor-on-idle] Marks one token as no longer outstanding, against
     * whatever it was owed by: the actor it targets, the pool a task will run
     * on, or the pool of the frame parked on it. Clamped at zero, so a double
     * release cannot go negative.
     */
    private fun release(target: SalvoTarget) {
        when (target) {
            is SalvoTargetProc -> actors[target.addr].owed = clamp(actors[target.addr].owed - 1)
            is SalvoTargetTask -> pools[target.pool].owed = clamp(pools[target.pool].owed - 1)
            is SalvoTargetWaiter -> {
                val pool = waiters[target.wid].pool
                pools[pool].owed = clamp(pools[pool].owed - 1)
            }
        }
    }

    private fun clamp(n: Int): Int = if (n < 0) 0 else n

    /**
     * [actor-on-idle] Hands a token over to the scheduler: it stops counting as
     * an obligation the program owes, because the scheduler is now the one who
     * will answer it. Used by [watch] and [onIdle], which is why a steady-state
     * program with registrations outstanding still reports zero.
     */
    private fun untrack(reply: SalvoReply) {
        if (reply.tracked) {
            reply.tracked = false
            release(reply.target)
        }
    }

    /**
     * [actor-on-idle] What an `Idle` payload says about a pool: how many actors
     * placed there have a gated mailbox, and how many reply tokens aimed at
     * work there nobody has discharged. Both zero is "done"; either non-zero is
     * "idle and still owed something".
     */
    private fun parked(pool: Int): Pair<Int, Int> {
        val gates = actors.count { it.pool == pool && it.gate != null && !it.dead }
        val tokens = actors.filter { it.pool == pool }.sumOf { it.owed } + pools[pool].owed
        return Pair(gates, tokens)
    }

    /**
     * [actor-on-idle] Fires every registered quiescence hook, if the scheduler
     * has settled. Answers whether anything fired — which is *progress*, so a
     * caller about to declare a deadlock has to look again first.
     *
     * Registrations are one-shots and all of them fire together: quiescence is
     * a property of the whole scheduler, so there is no order in which one hook
     * could see it and another not.
     */
    private fun fireIdle(): Boolean {
        if (idleHooks.isEmpty() || !idle()) {
            return false
        }
        val hooks = idleHooks.toList()
        idleHooks.clear()
        for ((pool, notify, build) in hooks) {
            val (gates, tokens) = parked(pool)
            deliverReply(notify, build(gates, tokens))
        }
        cv.signalAll()
        return true
    }

    /**
     * [waitfor-pump] The next job a thread working for [pool] may run:
     * [exclude] is the actor whose own activation is waiting, which a wait
     * must never serve — re-entering an actor mid-activation is precisely
     * what serialization exists to prevent. A pool worker excludes nothing.
     */
    private fun pick(
        pool: Int,
        exclude: Int?,
    ): Pair<Int, Int>? =
        actors.withIndex().firstNotNullOfOrNull { (i, p) ->
            if (p.pool != pool || i == exclude) null else deliverable(p)?.let { Pair(i, it) }
        }

    /**
     * The deadlock report [actor-watch] [waitfor-pump]: nothing can run while a
     * frame waits, so nothing can ever change — a named error instead of a
     * silent hang. [waiter] names the frame that is waiting, which since
     * [waitfor-effect] need not be main.
     *
     * The two lists are the two ways a mailbox comes to be unservable, and a
     * diagnosis starts by reading them: an actor **parked in a wait** holds its
     * own `running` flag, so *nothing* of its mailbox is delivered by anybody
     * until its token arrives; a **gated** actor serves only the reply it is
     * waiting for.
     */
    private fun reportDeadlock(waiter: Int?): Nothing {
        val occupied = waiters.filter { it.parked && it.parkedActor != null }.map { "actor ${it.parkedActor}" }
        val gated =
            actors.withIndex().filter { it.value.gate != null && !it.value.dead }.map { "actor ${it.index}" }
        val who = if (waiter == null) "main" else "actor $waiter"
        val clauses = mutableListOf<String>()
        if (occupied.isNotEmpty()) {
            clauses.add("parked in a wait: ${occupied.joinToString(", ")}")
        }
        if (gated.isNotEmpty()) {
            clauses.add("parked gates: ${gated.joinToString(", ")}")
        }
        val detail = if (clauses.isEmpty()) "" else " (${clauses.joinToString("; ")})"
        System.err.println("salvo: deadlock: nothing can run while $who waits$detail")
        kotlin.system.exitProcess(1)
    }

    /**
     * Runs one activation to completion. Called with the lock held and
     * answers with it held, releasing it for the body itself: a fault is
     * caught at this boundary and becomes the actor's death. Both callers —
     * a pool worker and a `waitfor` pumping its own pool [waitfor-pump] — go
     * through here, so an activation means the same thing whichever thread
     * runs it.
     */
    private fun runJob(
        addr: Int,
        at: Int,
    ) {
        val p = actors[addr]
        val entry = p.queue.removeAt(at)
        if (entry is SalvoEntry.User) {
            p.userLen -= 1
        }
        if (entry is SalvoEntry.Reply && p.gate == entry.slot) {
            p.gate = null
        }
        val body = p.body
        p.body = null
        p.running = true
        active += 1
        cv.signalAll() // a user entry left the queue
        lock.unlock()

        // The activation runs *here*: an ambient mint inside it inherits this
        // pool, and a nested wait must not serve this actor [waitfor-pump].
        val spot = here.get()
        here.set(SalvoHere(p.pool, addr, frame = true))
        val ctx = SalvoCtx(addr)
        var fault: String? = null
        try {
            when (entry) {
                is SalvoEntry.User -> body!!.handle(ctx, entry.msg)
                is SalvoEntry.Reply -> body!!.resume(ctx, entry.slot, entry.value)
            }
        } catch (t: Throwable) {
            fault = t.message ?: t.javaClass.simpleName
        } finally {
            here.set(spot)
            lock.lock()
        }
        p.running = false
        active -= 1
        // A local `val`, because a captured `var` does not smart-cast
        // inside a lambda and the `Exit` builder wants a `String`.
        val reason = fault
        if (reason == null) {
            p.body = body
        } else {
            p.dead = true
            p.exitReason = reason
            p.queue.clear()
            p.userLen = 0
            p.gate = null
            val watchers = p.watchers.toList()
            p.watchers.clear()
            for ((w, exit) in watchers) {
                deliverReply(w, exit(reason))
            }
            // [pool-fault-sink] The net under supervision: a death nobody was
            // watching still reaches the pool's sink, or the named report.
            if (watchers.isEmpty()) {
                reportFault(p.pool, reason)
            }
        }
        cv.signalAll()
    }

    /**
     * [task-mint] Runs one detached task to completion, with the same lock
     * discipline and fault boundary as an activation: the lock is released for
     * the body, and a fault is caught here. A task has no identity, so there
     * is nothing to mark dead and nobody to notify — the fault goes to the
     * pool's sink [pool-fault-sink], or to the named report when it has none.
     */
    private fun runTask(pool: Int) {
        val job = pools[pool].tasks.removeFirstOrNull() ?: return
        active += 1
        lock.unlock()

        // A task belongs to no actor, so a nested wait inside it may serve
        // every activation on the pool [waitfor-pump].
        val spot = here.get()
        here.set(SalvoHere(pool, null, frame = true))
        var fault: String? = null
        try {
            job.first(job.second)
        } catch (t: Throwable) {
            fault = t.message ?: t.javaClass.simpleName
        } finally {
            here.set(spot)
            lock.lock()
        }
        active -= 1
        val reason = fault
        if (reason != null) {
            reportFault(pool, reason)
        }
        cv.signalAll()
    }

    /**
     * [pool-fault-sink] Where an uncaught fault on a pool goes: a message to
     * the pool's sink actor if it has one, else a named report on stderr. A
     * fault that cannot be delivered (a dead sink) falls back to the report,
     * since the alternative is losing it silently.
     */
    private fun reportFault(
        pool: Int,
        reason: String,
    ) {
        val addr = pools[pool].sinkAddr
        val build = pools[pool].sinkBuild
        if (addr != null && build != null && !actors[addr].dead) {
            // Enqueued past the bound deliberately: a fault report must not
            // block the faulting thread, and dropping it would lose the one
            // thing the sink exists for.
            actors[addr].queue.addLast(SalvoEntry.User(build(reason)))
            actors[addr].userLen += 1
            return
        }
        System.err.println("salvo: an uncaught fault on pool $pool: $reason")
    }

    private fun worker(pool: Int) {
        here.set(SalvoHere(pool, null))
        lock.lock()
        try {
            while (true) {
                // [task-mint] A queued task before an activation: one rule,
                // the same on both backends, so a program's interleaving does
                // not depend on its target. Each queue is served in arrival
                // order.
                if (pools[pool].tasks.isNotEmpty()) {
                    runTask(pool)
                    continue
                }
                val job = pick(pool, null)
                if (job == null) {
                    // [actor-on-idle] A worker with nothing to do is the other
                    // place quiescence is observed: a hook registered from an
                    // actor is fired by whichever thread next runs dry, without
                    // anybody having to wait for it.
                    if (!fireIdle()) {
                        cv.await()
                    }
                } else {
                    runJob(job.first, job.second)
                }
            }
        } finally {
            lock.unlock()
        }
    }
}

internal sealed class SalvoTarget

internal class SalvoTargetProc(val addr: Int) : SalvoTarget()

internal class SalvoTargetWaiter(val wid: Int) : SalvoTarget()

/** [task-mint] A detached one-shot: the pool it runs on, and the closure. */
internal class SalvoTargetTask(val pool: Int, val body: (Any?) -> Unit) : SalvoTarget()

/**
 * A one-shot reply capability. `send` delivers exactly once — the
 * guarantee is the checker's; the runtime only enqueues.
 */
class SalvoReply internal constructor(internal val target: SalvoTarget, internal val slot: Long) {
    /**
     * [actor-on-idle] Whether this token still counts as an obligation the
     * program owes. A mint counts it; a delivery, or a handover to the
     * scheduler itself ([SalvoSched.watch], [SalvoSched.onIdle]), stops
     * counting it — what an `Idle` payload reports is work *user code* has not
     * answered, not registrations the scheduler will answer on its own.
     */
    internal var tracked: Boolean = true

    fun send(value: Any?) = SalvoSched.sendReply(this, value)
}
